def emit_sdk(endpoints: list[dict], source_url: str) -> str:
    lines = [
        '"""Generated by Auto-SDK Architect."""',
        "import httpx",
        "",
        "class Client:",
        "    def __init__(self, base_url: str):",
        "        self._http = httpx.Client(base_url=base_url)",
        "",
    ]
    
    # Sort to ensure determinism
    for ep in sorted(endpoints, key=lambda e: (e["path"], e["method"])):
        method_name = ep["method"].lower() + "_" + ep["path"].strip("/").replace("/", "_").replace("{", "").replace("}", "")
        params = ", ".join(f"{p['name']}: {p['type']}" for p in ep["params"]) or ""
        
        lines.append(f"    def {method_name}(self{', ' + params if params else ''}):")
        lines.append(f"        return self._http.request({ep['method']!r}, {ep['path']!r})")
        lines.append("")

    code = "\n".join(lines)
    compile(code, "sdk.py", "exec")  # Ensure it compiles
    return code